#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    int a[10]; for(int i=0;i<10;i++) cin>>a[i];

    vector<vector<int>> adj(n+1), radj(n+1);
    vector<unordered_set<int>> aset(n+1);

    for(int i=0;i<m;i++){
        int u,v; cin>>u>>v;
        adj[u].push_back(v);
        radj[v].push_back(u);
        aset[u].insert(v);
    }

    auto has=[&](int u,int v)->bool{ return aset[u].count(v); };

    auto now=chrono::steady_clock::now;
    auto st=now();
    auto ms=[&]()->long long{ return chrono::duration_cast<chrono::milliseconds>(now()-st).count(); };

    mt19937 rng(12345);
    vector<int> best;

    auto try_build=[&](int sv){
        vector<int> path;
        vector<bool> used(n+1, false);
        path.push_back(sv);
        used[sv] = true;

        // Extend back and front with rotation
        for(int phase = 0; phase < 2000 && ms() < 3800; phase++){
            // Try extend back
            {
                int tail = path.back();
                vector<int> cands;
                for(int v : adj[tail]) if(!used[v]) cands.push_back(v);
                if(!cands.empty()){
                    int pick = cands[rng() % cands.size()];
                    path.push_back(pick);
                    used[pick] = true;
                    continue;
                }
            }
            // Try extend front
            {
                int head = path[0];
                vector<int> cands;
                for(int v : radj[head]) if(!used[v]) cands.push_back(v);
                if(!cands.empty()){
                    int pick = cands[rng() % cands.size()];
                    path.insert(path.begin(), pick);
                    used[pick] = true;
                    continue;
                }
            }
            // Rotation: tail connects to some path[j], reverse path[j+1..end]
            {
                int tail = path.back();
                vector<int> rot_cands;
                for(int j = 0; j + 1 < (int)path.size(); j++){
                    if(has(tail, path[j])){
                        rot_cands.push_back(j);
                    }
                }
                if(!rot_cands.empty()){
                    int j = rot_cands[rng() % rot_cands.size()];
                    // reverse from j+1 to end
                    reverse(path.begin()+j+1, path.end());
                    continue;
                }
            }
            // Similar rotation on front
            {
                int head = path[0];
                vector<int> rot_cands;
                for(int j = 1; j < (int)path.size(); j++){
                    if(has(path[j], head)){
                        rot_cands.push_back(j);
                    }
                }
                if(!rot_cands.empty()){
                    int j = rot_cands[rng() % rot_cands.size()];
                    reverse(path.begin(), path.begin()+j);
                    continue;
                }
            }
            break;
        }

        // Vertex insertion
        for(int v = 1; v <= n; v++) if(!used[v]){
            if(has(v, path[0])){ path.insert(path.begin(),v); used[v]=true; continue; }
            if(has(path.back(),v)){ path.push_back(v); used[v]=true; continue; }
            for(int i=0;i+1<(int)path.size();i++){
                if(has(path[i],v)&&has(v,path[i+1])){
                    path.insert(path.begin()+i+1,v); used[v]=true; break;
                }
            }
        }

        if((int)path.size() > (int)best.size()) best = path;
    };

    vector<int> order(n); iota(order.begin(),order.end(),1);
    shuffle(order.begin(),order.end(),rng);

    for(int i=0; i<n && ms()<3800; i++){
        try_build(order[i]);
        if((int)best.size() >= n) break;
    }

    cout << best.size() << "\n";
    for(int i=0;i<(int)best.size();i++){
        if(i) cout<<' ';
        cout<<best[i];
    }
    cout<<"\n";
}
